"""Audit raw x87 payload semantics and explicit pointer/opcode update profiles."""
import hashlib,json,sys,zipfile
from pathlib import Path
from tools.cfg_recover_startup import sha,write_json
root=Path.cwd();out=Path(sys.argv[1]);out.mkdir(parents=True,exist_ok=False)
def read(p):return json.loads(p.read_text(encoding='utf-8'))
base=root/'local/compiler-spike';sem=root/'build/extended-semantics-v23-raw-profile';identity=read(sem/'identity.json');assert sha(sem/'amd64_avx.bc')==identity['semantics_sha256']
for name,digest in identity['extension_sha256'].items():assert sha(Path(name))==digest
observations={}
for name,count in [('x87-raw-bindings-v1',344072),('x87-raw-bindings-v2-flags',344072),('x87-raw-bindings-v4-profile',688144),('x87-raw-bindings-v5-opcode',688144),('x87-stack-probe-v5-raw',1499136),('x87-image-bindings-v4-raw',557864)]:
 p=base/name;s=read(p/'summary.json');groups=[json.loads(line) for line in (p/'execute.stdout').read_text(encoding='utf-8').splitlines()]
 assert s['cases']==count and s['groups']==groups and s['differing_cases']==sum(g['differing_cases'] for g in groups) and s['raw_sha256']==sha(p/'execute.stdout')
 assert s['differing_cases']==(10956 if name=='x87-raw-bindings-v1' else 0)
 if name in ['x87-raw-bindings-v4-profile','x87-raw-bindings-v5-opcode','x87-stack-probe-v5-raw','x87-image-bindings-v4-raw']:assert s['semantics_sha256']==identity['semantics_sha256']
 observations[name]=s
raw=observations['x87-raw-bindings-v5-opcode'];groups=raw['groups'];assert sum(g['hardware_faults'] for g in groups)==190914 and sum(g['native_faults'] for g in groups)==190922 and sum(g['unsupported_cases'] for g in groups)==8
assert all(not any(g['differences'].values()) and g['pointer_observation_differences']==g['opcode_observation_differences']==0 for g in groups)
assert sum(g['pointer_observation_differences'] for g in observations['x87-raw-bindings-v2-flags']['groups'])==99146
pointer=read(base/'x87-pointer-update-probe-v1/summary.json');assert pointer['cpu']==dict(cpuid7_ebx=597436329,fdp_exception_only=0,cs_ds_deprecated=1) and pointer['raw_sha256']==sha(base/'x87-pointer-update-probe-v1/execute.stdout')
assert sum(g['cases'] for g in pointer['groups'])==1920
for g in pointer['groups']:
 assert g['dp_updated_no_unmasked_exception']==g['dp_preserved_unmasked_exception']==g['dp_other_no_unmasked_exception']==g['dp_other_unmasked_exception']==0
 assert g['fop_updated_no_unmasked_exception']==g['fop_preserved_unmasked_exception']==0 and g['fop_updated_unmasked_exception']==g['dp_updated_unmasked_exception']
failed=(base/'x87-raw-bindings-v3-pointers/execute.stderr').read_text(encoding='utf-8');assert 'fdp-exception-only=0' in failed and 'host FDP calibration feature missing' in failed
runs={}
for suffix in ['extended-semantics-v20-raw','x87-raw-prepare-v1','x87-raw-bindings-v1','extended-semantics-v21-raw-flags','x87-raw-bindings-v2-flags','extended-semantics-v22-raw-pointers','x87-raw-bindings-v3-pointers','x87-pointer-update-probe-v1','extended-semantics-v23-raw-profile','x87-raw-bindings-v4-profile','x87-raw-bindings-v5-opcode','x87-stack-probe-v5-raw','x87-image-bindings-v4-raw']:
 name='20260906-p3-'+suffix;p=root/'local/runs'/name;m=read(p/'manifest.json');assert m['status']==('failed' if suffix in ['x87-raw-bindings-v1','x87-raw-bindings-v3-pointers'] else 'pass')
 with zipfile.ZipFile(p/'sources.zip') as z:
  for path,digest in m['source_sha256'].items():assert hashlib.sha256(z.read(path.replace(chr(92),'/'))).hexdigest()==digest
 runs[name]=dict(status=m['status'],source_commit=m['project_commit'],sources_sha256=sha(p/'sources.zip'),elapsed_seconds=m['elapsed_seconds'])
ir=(base/'x87-raw-bindings-v5-opcode/function.ll').read_text(encoding='utf-8');assert '__remill_fpu_' not in ir and '@__bb_native_x87_record_instruction' in ir and '@__bb_native_x87_check_span' in ir and '@__bb_native_x87_image_policy' in ir
accepted=root/'build/extended-semantics-v9-sqrt';assert sha(accepted/'amd64_avx.bc')==read(accepted/'identity.json')['semantics_sha256']
report=dict(status='experimental raw x87 payload/flag/boundary contracts passed under explicit profiles; P3 remains open',raw=raw,observations=observations,pointer_update_probe=pointer,runs=runs,source_sha256={p:sha(root/p) for p in ['native/semantics/X87_RAW.cpp.inc','native/semantics/x87_raw_fixture.cpp','native/semantics/x87_pointer_update_probe.cpp','tools/x87_raw_experiment.py','tools/x87_pointer_update_probe.py']},retained_failures={'raw-v1':'10956 C1 differences: source-empty priority on register loads and ordinary FCMOVNE C1 preservation. All raw outputs are retained.','raw-v2-limits':'Selected contracts passed, but 99146 FDP observations disagreed with the naive always-update host oracle. This was not full pointer agreement.','raw-v3':'The fixture assumed FDP exception-only observations required CPUID.7.0:EBX[6]=1. This CPU reports 0. The failed guard is retained; a separate hardware probe characterizes actual behavior without that inference.'},primary_sources=['https://cdrdv2-public.intel.com/812383/253666-sdm-vol-2a.pdf','https://cdrdv2-public.intel.com/671110/325383-sdm-vol-2abcd.pdf','https://www.intel.com/content/dam/support/us/en/documents/processors/pentium4/sb/25366521.pdf','https://cdrdv2-public.intel.com/812218/architecture-instruction-set-extensions-programming-reference.pdf'],limitations=['Authored AOT only. Five raw selectors are replaced; no game code was executed or newly accepted.','C0/C2/C3 are architecturally undefined for the tested operations and excluded from the hardware status oracle. Other State, payload, memory, flags and defined status effects are checked.','Both explicit profiles have checked State and metadata contracts. The always-update profile is an explicit policy, not an AMD Jaguar hardware observation.','Host FIP/FDP comparisons use low 32 bits to avoid the separately observed host upper-pointer loss. Canonical native pointers retain full logical values. FOP is checked with exact authored opcode mapping after accounting for the different hardware memory base register.','The independent hardware probe uses FXRSTOR input setup and no Remill/SoftFloat/SEH path. CPUID.7.0:EBX[6]=0 does not by itself prove always-update behavior; no inverse CPUID implication or universal hardware rule is claimed.','Pointer metadata is an explicit runtime service keyed by exact decoded PC. The fixture uses CS/DS for its authored operands; general segment selection must come from compilation metadata.','Older x87 producers still require the same explicit pointer/opcode policy, and FNINIT must reset segment metadata. Memory conversions/arithmetic, unmasked numeric results and MMX coherence remain open.','Eight unsupported span cases and eight extra native pending-before-unsupported cases are separate from the 190914 matched hardware faults. General guest mapping and PS4/Windows guest fault delivery remain unimplemented.'],experimental_semantics='v23-raw-profile',accepted_semantics='v9-sqrt',compiled_entries=21168,remaining_compiler_rejections=2,remaining_quarantined_entries=8,native_game_boot=False,native_port_playable=False)
write_json(root/'reports/x87-raw-evidence.json',report);summary=dict(status=report['status'],cases=688144,hardware_faults=190914,native_pending_before_unsupported=8,unsupported_cases=8,experimental_semantics_sha256=identity['semantics_sha256']);write_json(out/'summary.json',summary);print(json.dumps(summary),flush=True)
